import{b as e,O as t,g as c,j as l}from"./chunks/framework.DcaUmd3X.js";const i=JSON.parse('{"title":"沟通的艺术","description":"","frontmatter":{},"headers":[],"relativePath":"reading/digital/art-of-communication/index.md","filePath":"读书感悟/电子书架/5.沟通的艺术.md","lastUpdated":1781614933000}'),p={name:"reading/digital/art-of-communication/index.md"};function u(b,o,k,q,a,r){return t(),c("div",null,[...o[0]||(o[0]=[l('<h1 id="沟通的艺术" tabindex="-1">沟通的艺术 <a class="header-anchor" href="#沟通的艺术" aria-label="Permalink to &quot;沟通的艺术&quot;">​</a></h1><p><code>卡耐基</code> <code>沟通表达</code></p><h2 id="书摘" tabindex="-1">书摘 <a class="header-anchor" href="#书摘" aria-label="Permalink to &quot;书摘&quot;">​</a></h2><blockquote><p>📌 学会在他人面前清晰地表达自己的思想和意念，使之传递给他人。</p></blockquote><blockquote><p>📌 要想成功，必须具备的条件就是，用你的欲望提升自己的热忱，用你的毅力磨平高山，同时还要相信自己一定会成功。</p></blockquote><blockquote><p>📌 不久前，我曾问大西洋城的外科医师兼美国医药学会的前任会长大卫·奥门博士，从心理和生理健康的角度来看，他认为当众演说训练的益处如何？他微笑着回答了这个问题。他说最好是开个处方，这个处方是“药房里抓不到药的，个人得自己配药；他要以为自己不行，他就错了。” 我桌上就放着这么一份处方，每读一次，都觉得心有感触。以下便是奥门博士振笔疾书的处方： 尽力培养一种能力，让别人能够窥视你的脑海和心灵。学会在他人面前清晰地表达自己的思想和意念，使之传递给他人。</p></blockquote><blockquote><p>📌 一天早晨用早餐的时候，我翻开《弗吉尼亚导报》，其中赫然印有一幅乔的照片与一篇称誉他的报道。前一天晚上，他在地区建造商的盛大聚会中发表演说，在我看来，乔岂止是全国房屋建造协会的发言人，他其实就是一名会长了。 因此，要想成功，必须具备的条件就是，用你的欲望提升自己的热忱，用你的毅力磨平高山，同时还要相信自己一定会成功。 当凯撒从高卢而来、船行海峡之上，最后和他的军团登陆于现在的英格兰时，他是如何确保自己军队成功的呢？</p></blockquote><blockquote><p>📌 可能。不过，现代实验心理学家都认为，由自我启发而产生动机，即使是佯装的，也是导致快速学习最有力的刺激之一。 第四，表现得信心十足 美国本土著名心理学家威廉·詹姆斯写道： 行动似乎显得是紧随于感觉之后的，但事实上行动与感觉是并行的，行动受意念的直接控制。同样，通过制约行动，我们可以间接制约感觉，而它是不受意志直接控制的。 因此，假若我们失去了原有的自然欢乐，那么通往欢乐的最佳方法便是快快乐乐地坐起、说话，表现得一如欢乐就在那里。</p></blockquote><blockquote><p>📌 事实上，面对听众之前，应深呼吸30秒，增加氧气供应可以提神，给你勇气。杰出的男高音佳恩·雷斯基常说，如果你气充胸臆，可以“席气而坐”，紧张感便自然消逝得无影无踪了。 身体站直，直入听众的眼里，然后开始信心十足地讲话，好似他们每个人都欠你钱似的。假想他们欠你的债，假想他们聚在那里要求你宽限还债的时间。这种心理作用对你将大有帮助。 如果你怀疑这种理论没有道理，你可以找一位参加过我训练班的学员问一问，他们早就接纳了本书的意见。</p></blockquote><blockquote><p>📌 在这段话里，一艘小型英国军舰的舰长向主角解说如何保持无畏无惧。他说，起初临到有所行动时，人人都会害怕，不过他应依循一个法则——驾驭自己，使自己表现得好像无所畏惧。只要这样持之以恒，原先的假设就会变成事实，而他只不过是通过练习一种无畏的精神而不知不觉地变成了无惧的勇士。 这便是我据以训练自己的理论。刚开始，我害怕的事情真多，从大灰熊、野马到枪手，无一不怕，可是我总是表现得好似不怕的样子，渐渐地我便停止了害怕。</p></blockquote><blockquote><p>📌 早年成长的历程——与家庭、童年回忆、学校生活有关的题目，一定会吸引他人的注意。因为别人在成长的环境里如何面对并克服阻碍的经历，最能引起我们的兴趣。 不论何时，只要有可能，就把自己早年的实例穿插在讲演中。你还可以运用一些脍炙人口的戏剧、电影和故事、人们早年遭遇的挑战等。但是，我们怎样才能确定别人会对自己小时候所发生的事情感兴趣呢？有个办法可以测试。多年之后，如果某件事依旧鲜明地印在自己的脑海中，呼之欲出，那几乎便可确定会令听众感兴趣了。</p></blockquote><blockquote><p>📌 第三，激发听众与你产生共鸣 凡是讲演情况皆由三个要素构成：讲演者、演讲词（内容）以及听众。本章的前两条法则都是讨论讲演人和演讲词之间的相互关系，直至目前为止，我们还没有真正谈到演说时的情形。唯有讲演者使自己的讲演与活生生的听众发生关联之后，讲演的情况才真正形成。讲演也许准备周详，也许是关于讲演者所热衷的话题。然而要真正完全成功，还有另一个因素需要考虑：他必须使听者觉得他所要说的很重要；他不只是要对自己的话题充满热情，还要把这种热情传递给听众。</p></blockquote><blockquote><p>📌 我们如何才能获得使用实例的技巧呢？有五种方法可供选择：人性化、个人化、翔实化、戏剧化和视觉化。下面就让我们具体谈谈这五种方法。 谈话要具有人情味 有一次，我要巴黎的一群美国商人就“成功之道”发表讲演。他们大多数人都只列举了一大串抽象的特征，并且大谈什么勤奋工作、坚持不懈和远大抱负的价值。 因此，我便中止了上课，说出了以下的这番话：“我们都不想听人说教，没有谁会喜欢这样。</p></blockquote><blockquote><p>📌 关于这点，你也许会说：“这样当然好啦。但是我又怎能确知是否在讲演里收录了足够的细节？”有个方法可以测试。利用新闻记者写一桩新闻故事时所遵循的“五W公式”：何时（When）、何地（Where）、何人（Who）、何事（What）、何故（Why），假如你也依照这个公式来做，你的举例便会生意盎然，多彩多姿。我且举出自己的一件趣事来加以说明。这则趣事曾刊登在《读者文摘》上： 离开大学以后，我花了两年的时间在南达柯达州到处跑，从事铁甲公司的销售员。我四处游走，都靠搭乘运货卡车。</p></blockquote><blockquote><p>📌 班上的学员以此作为游戏，彼此监督对方所犯的毛病。没多久，大家的谈话都不再模糊不清，而使听众一团迷雾了，他们说的是街上寻常人所用的明确而活泼的言语。 法国哲学家艾兰说：“抽象的风格并不好，在你的句子里应该充满了石头、金属、椅子、桌子、动物、男人和女人等这类具体而有生命力的字眼。” 日常对话也是如此。我们在前面曾经说过的有关当众说话时使用的细节技巧，同样也适用于一般性的交谈。只有细节才能使得谈话焕发生气和光彩。</p></blockquote><blockquote><p>📌 在备选题目中，有一类题目是保证错不了的，那就是谈自己的信念。你对自己生活周遭的某方面一定具有某种强烈的信仰，因此你不必上天入地去寻觅这些题材。它们通常就在你的意识层面，因为你时常会想到它们。 不久以前，电视播出立法委员就死刑而举行的听证会。许多证人被召出席，对这个为人争论不休的问题提出正反两方面的意见。其中之一是洛杉矶警署的一员。很明显，他曾对这个问题思考再三。他有11位警察同伴，都死于和罪犯搏斗的枪战中。</p></blockquote><blockquote><p>📌 根据这项事实，他心中萌发了对于死刑必要性的强烈信念。他说得情深意挚，从心坎里相信自己的理由是正确的。历来的雄辩中，其最大吸引力，皆出于一个人深切的信念和感觉。真诚建立在信仰之上，而信仰则出于一心对自己所要说的事情的温馨情感，出于脑子对于要说什么的冷静思考。“此心自有道理，是为道理所不自知。”在众多的班次里，我常有机会验证帕斯卡以上这句锋锐有力的话。记忆中，有位波士顿的律师，得天独厚，仪表出众，说话流畅可嘉，但是他讲演完了之后同学都说：“好个精明的家伙。”</p></blockquote><blockquote><p>📌 当我想要他停下来时，他正说到有关鸽子的四十本书，而这些他都已拜读过了！他的讲演是我听过最有趣味的讲演之一。 这里还有一个建议：对自己目前认为很好的题目设法多了解一点。对某种事情了解得愈多，你对它便会愈热诚、愈热衷。《销售的五大法则》的作者帕西·H·怀亭告诉推销员，万万不可不去了解自己所售卖的东西。怀亭先生说：“对一项优良产品知道得愈多，便会对它愈热心。”此种情形用之于讲演题目也是如此——对它们懂得越多，你对它们也就越热诚、越热衷。</p></blockquote><blockquote><p>📌 但销量并没有就此停住，而是继续上升了好几年。西德达满足了读者们的第一兴趣。 因此，当你下次面对听众时，设想他们急切要听你说些什么——只要能适用于他们。讲演者若不能考虑到听众自我中心的必然倾向，很容易便会发现自己面对的是一些烦躁不安的听众。他们局促不安，不时瞥看手表，并且看着出口。 第二，给予最真诚的赞赏 听众是由很多个体构成的，因此他们的反应就和个人一样。公然批评听众必会导致愤懑。对他们做过的值得称赞的事表示赞美，你就已经获得了通往他们心灵的护照。</p></blockquote><blockquote><p>📌 另外，还有一个办法可以使听众的注意力保持在巅峰状态，那就是采用代名词“你”而不要用“他们”。这种方式可以使听众保持在一种自我感知的状态中。这一点我在前面已经指出，演说者如想把握听众的注意和兴趣，是不能忽视这一因素的。下面摘录了题为《硫酸》的讲演中的几段——这是我们纽约某个训练班里的一个学员所说的： 硫酸和我们日常生活的很多方面都有关系。如果没有硫酸，你的汽车将无法行驶，你必须像古时候那样骑马或驾驶马车，因为在提炼煤油及汽油时，必须广泛应用到硫酸。</p></blockquote><blockquote><p>📌 你对某些事的态度要正确，”怀廷先生说，“要知道，演讲和背诵不同，演讲的用意在于获得听众的反应——要让听众在整个事件中变成参与者”。我喜欢他把听众描述为“整个事件的参与者”。这也是本章所讨论的一切关键所在。如果你能让听众参与，他便成为了你的好伙伴。 第五，采取低姿态 当然，在讲演者与听众的关系里，真诚是无可替代的。</p></blockquote><blockquote><p>📌 爱德蒙·S·穆斯基在缅因州任参议员时，曾对在波士顿的美国辩论协会讲话，其中便展示了这种技巧。 “今天早晨我迟疑着不知是否该接下这份演讲的任务，”他说道，“首先，我知道来的听众都是具有专业水准的人士，于是我不免自问：如此班门弄斧，在各位锐利的眼光面前暴露自己的愚拙，是否明智。其次，这是个早餐会，通常是人们最没有警觉性的时刻。因此，如果我表现得不好，这对于一位政客而言，其后果是十分严重的。其三，我今天要讲的主题是：身为一名公仆，究竟有什么影响力？</p></blockquote><blockquote><p>📌 以下是颇吸引我的一些开场白：“在1942年，我发现自己躺在医院的病床上”、“昨天早餐的时候，我太太正在倒咖啡，这时”、“去年7月，我开着我那辆跑车在42号公路上飞驰”、“我办公室的大门猛地打开，我看见我们的工头查理·范冒冒失失地闯进来”、“我正在湖边钓鱼，一抬头，却见到一艘汽艇朝我快速驶过来”，假如你的开场白能回答“五个W”和“一个H”中任何一个问题，即“谁（who）”、“何时（when）”、“何地（where）”、“何事（what）”、“为何（why）”“如何（how）”。</p></blockquote><blockquote><p>📌 正如我们在前面章节曾提到的，准备一场演讲的作业，就是回答如下种种问题：何人？何时？何地？如何？为何？等等。你必须用丰富的词汇和特定的语气去引发听众的想像力。 将你的经历再现给听众 除了利用详实的细节描述之外，演讲人还必须在描述事件时，使自己的经历得到重现，这样才有可能达到促使别人采取行动的地步。伟大的演说家都具有表演天赋，这并非是特别稀有的品质，许多小孩就富有这种才能。在我们所熟识的许多人中，有的人天生具有节奏感、脸部表情、模仿或演哑剧等禀赋，这都是表演的可贵资质。</p></blockquote><blockquote><p>📌 主张的内容要易于实践 无论你所谈论的主题是否会引起争论，演讲人都必须把自己的主张陈述出来，以便使听众能容易理解并采取行动。最好的方法便是让你的主张明确而具体。假如你要听众加强记忆姓名的能力，不要说：“现在开始加强你们对姓名的记忆力。”那样实在虚无缥渺，让人很难去实践。最好改成：“下次你见陌生人的时候，要在五分钟内，把这人的姓名重复默念五次。” 能够把付诸行动的主张详尽告知听众的演讲人，要比那些只泛泛提及的演讲人更能鼓励听众采取行动。</p></blockquote><blockquote><p>📌 拉威格·韦泽斯坦曾说过： “一件事，若能被思考，必能被思考得很清楚；一件事，若能被讲出来，也必能被讲得很清楚。” 第一，限制题材，以配合特定的时间 威廉·詹姆斯教授有次对教师们谈话时指出，在一场演讲当中，最好限定自己只讲一个论点。他所指的一场演讲，是指持续达一个小时的演讲。但最近，我听见一位演讲人在一开始时便宣称，他要在指定的3分钟内提到11个论点，也就是每个论点只分配到16秒半！这真是不可思议！</p></blockquote><blockquote><p>📌 假定你现在应邀到“劳工联盟”发表演讲，千万别想在短短的三分钟或六分钟之内告诉他们，联盟何以诞生、如何雇佣员工、完成了些什么任务、做了些什么不对的事，或是解决了哪些纷争等。不，千万不要这样！假如你执意如此，那么没有人会对你所讲的东西有十分清楚的概念。他们甚至会被弄得糊里糊涂，对每个主题都只有模糊的轮廓，没有清楚的内容。 所以，假如你只选择一个主题，而且仅此一个，这不是要显得更聪明些吗？你可以就劳工联盟的题材选出一个问题来谈，然后收集尽可能多的资料，描述得详尽一些。</p></blockquote><blockquote><p>📌 他们甚至难以相信自己也能培养出这种能力。 我相信，假如这些人可以做得到，其他人也一样可以做得到——只要具有意志力和信心——而且，你愈常练习，事情就愈变得容易。 另一个用来训练即兴谈话的方法，叫做“接龙”。先由一个学员开始讲故事，然后再由其他人继续接下去。举例来说，第一个学员可能这么开始：“有一天，我正驾着直升机，忽然发现一群飞碟逐渐向我飞来。我开始下降，但离我最近的一个飞碟里，有个体格瘦小的人开始向我开火，我——”</p></blockquote><blockquote><p>📌 人们正是以这四种接触方式来对我们加以评量，并进行归类。这四种方式是：我们做了些什么、我们看起来是什么样子、我们说了些什么，以及我们怎样说。本章先讨论最后一项，即我们怎样说。 当我最初向当众教演说课程时，曾花费很多时间在发声练习上。主要是教导学生们利用共振，训练他们增大音量，并使尾音更加轻快活泼。但是，我不久便发觉，教导成年人如何把音调置于鼻窦中，以及如何形成“透亮”的母音，完全是徒劳无功的。 这项训练，对那些靠花上三四年时间来改进声音表达技巧的人而言，诚然是一种极好的方法。</p></blockquote><blockquote><p>📌 稍稍花点时间准备，我们便可避免对讲演者和听众造成如此恶劣的印象。 第二，遵从“题目—重要性—讲演者”公式 对大部分的介绍辞而言，题目——重要性——讲演者这个公式是个近便的指引，可帮助你组织所搜集的研究资料： 1.题目。宣布讲演者的正确讲题，然后展开介绍。 2.重要性。在这个阶段，要在题目和听众的特殊兴趣之间架起一座桥梁。</p></blockquote><blockquote><p>📌 然而就是这个人，他在家里穷读不休，到处勤练不辍，最终把自己塑造成了一名讲演者，进而得以与当时最杰出的雄辩家道格拉斯参议员展开世纪辩论，以一决雌雄。也就是这个人，在盖茨堡，接着又在第二次总统就职演说上，崇论宏议，冠绝古今。 想想自己身受的种种艰难挫折与令人心酸的奋斗，难怪林肯要说：“如果你已下定决心要做律师，事情已成功一半有余。”</p></blockquote>',31)])])}const d=e(p,[["render",u]]);export{i as __pageData,d as default};
